const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const gameRoot=process.env.EMBERWILD_GAME_ROOT||'/tmp/Emberwild';
const editorRoot=process.cwd();
const {loadRuntime}=require(path.join(gameRoot,'tests/headless-runtime.cjs'));
const json=(r,code)=>JSON.parse(r.run('JSON.stringify('+code+')'));
const html=fs.readFileSync(path.join(editorRoot,'balance-editor.html'),'utf8');
for(const text of ['觸發次數','可疊加','單體技能傷害擴散','排序能力','包含自己'])assert(html.includes(text),text+' editor UI missing');
const e=loadRuntime(editorRoot,'balance-editor.html');
assert.deepEqual(e.errors,[],'editor boot errors');
assert.deepEqual(json(e,'validateData()'),[],'editor validation failed');
const pain=json(e,`(()=>{const s=data.statusDefinitions.find(x=>x.id==='pain-spread'),p=data.supportSkills[3].find(x=>x.statusId==='pain-spread');return {s,p};})()`);
assert(pain.s,'Pain Spread status missing');
assert.equal(pain.s.uses,1);assert.equal(pain.s.stackable,false);
assert.equal(pain.s.modifiers[0].kind,'damageSpread');assert.equal(pain.s.modifiers[0].value,.3);assert.equal(pain.s.modifiers[0].targets,2);
assert(pain.p,'Pain Spread support skill missing');
assert.equal(pain.p.kind,'applyStatus');assert.equal(pain.p.statusTarget,'rankedAllies');assert.equal(pain.p.statusTargetStat,'attack');assert.equal(pain.p.statusTargetOrder,'highest');assert.equal(pain.p.statusTargetIncludeSelf,false);
const generic=json(e,`__EMBERWILD_STATUS_EDITOR_TEST_API.normalize({id:'spread-test',name:'Spread',tags:['modifier'],duration:5,uses:3,stackable:true,modifiers:[{kind:'damageSpread',value:.25,targets:4}]})`);
assert.equal(generic.uses,3);assert.equal(generic.stackable,true);assert.equal(generic.modifiers[0].targets,4);
const doc=json(e,'__EMBERWILD_MASTERY_EDITOR.cleanExport()');
const ds=doc.statusDefinitions.find(x=>x.id==='pain-spread'),dp=doc.supportSkills[3].find(x=>x.statusId==='pain-spread');
assert(ds&&dp,'clean export dropped Pain Spread');assert.equal(ds.uses,1);assert.equal(ds.stackable,false);assert.equal(ds.modifiers[0].targets,2);assert.equal(dp.statusTargetStat,'attack');assert.equal(dp.statusTargetOrder,'highest');assert.equal(dp.statusTargetIncludeSelf,false);
const g=loadRuntime(gameRoot);g.ctx.doc=doc;g.run('applyBalanceConfig(doc,{persist:false});');assert.deepEqual(g.errors,[],'game rejected editor export');
const out=json(g,'exportableBalance()'),gs=out.statusDefinitions.find(x=>x.id==='pain-spread'),gp=out.supportSkills[3].find(x=>x.statusId==='pain-spread');
assert(gs&&gp,'game export dropped Pain Spread');assert.equal(gs.uses,1);assert.equal(gs.stackable,false);assert.equal(gs.modifiers[0].targets,2);assert.equal(gp.statusTargetStat,'attack');assert.equal(gp.statusTargetOrder,'highest');assert.equal(gp.statusTargetIncludeSelf,false);
console.log('advanced status editor integration: ok');
